import React, { useEffect, useState } from 'react';
import { fetchRecords, createRecord, toggleRecordStatus, deleteRecord, type AppRecord } from './api/client';

export default function App() {
  const [records, setRecords] = useState<AppRecord[]>([]);
  const [label, setLabel] = useState('');
  const [category, setCategory] = useState('Core');
  const [val, setVal] = useState('');
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    void fetchRecords().then((data) => {
      setRecords(data);
      setLoading(false);
    });
  }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!label.trim()) return;
    const created = await createRecord({
      label: label.trim(),
      category,
      val: Number(val) || 0,
    });
    setRecords((prev) => [created, ...prev]);
    setLabel('');
    setVal('');
  };

  const visible = records.filter((r) => (filter === 'all' ? true : r.status === filter));

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 p-6">
      <div className="max-w-5xl mx-auto space-y-6">
        <header className="flex items-center justify-between border-b border-slate-800 pb-4">
          <div>
            <h1 className="text-2xl font-bold text-white">KanbanFlow - Task Board with Priority Filters</h1>
            <p className="text-xs text-slate-400">Build a task kanban board with priority filters</p>
          </div>
          <span className="text-xs font-mono text-emerald-400">Connected · /api/records</span>
        </header>

        <form onSubmit={handleCreate} className="grid grid-cols-1 sm:grid-cols-4 gap-3 bg-slate-900 p-4 rounded-2xl border border-slate-800">
          <input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            placeholder="Record title..."
            className="sm:col-span-2 px-3 py-2 rounded-xl bg-slate-950 border border-slate-800 text-sm"
          />
          <input
            type="number"
            value={val}
            onChange={(e) => setVal(e.target.value)}
            placeholder="Value"
            className="px-3 py-2 rounded-xl bg-slate-950 border border-slate-800 text-sm"
          />
          <button type="submit" className="px-4 py-2 rounded-xl bg-amber-400 text-slate-950 font-bold text-sm">
            + Add Record
          </button>
        </form>

        <div className="flex gap-2">
          {(['all', 'active', 'completed'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-3 py-1 rounded-lg text-xs font-bold ${filter === f ? 'bg-amber-400 text-slate-950' : 'bg-slate-900 text-slate-400'}`}
            >
              {f.toUpperCase()}
            </button>
          ))}
        </div>

        {loading ? (
          <div className="text-xs text-slate-400">Loading records...</div>
        ) : (
          <div className="space-y-2">
            {visible.map((item) => (
              <div key={item.id} className="flex items-center justify-between p-3.5 rounded-xl bg-slate-900 border border-slate-800">
                <div>
                  <div className="font-semibold text-white">{item.label}</div>
                  <div className="text-xs text-slate-400">{item.category} · {item.status}</div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="font-mono font-bold text-amber-400">${item.val.toLocaleString()}</span>
                  <button
                    onClick={async () => {
                      const updated = await toggleRecordStatus(item.id);
                      setRecords((prev) => prev.map((r) => (r.id === item.id ? updated : r)));
                    }}
                    className="text-xs text-emerald-400"
                  >
                    Toggle
                  </button>
                  <button
                    onClick={async () => {
                      await deleteRecord(item.id);
                      setRecords((prev) => prev.filter((r) => r.id !== item.id));
                    }}
                    className="text-xs text-rose-400"
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export interface AppRecord {
  id: number;
  label: string;
  category: string;
  val: number;
  status: 'active' | 'completed';
  createdAt: string;
}

export async function fetchRecords(): Promise<AppRecord[]> {
  const res = await fetch('/api/records');
  if (!res.ok) throw new Error('Failed to fetch records');
  return res.json();
}

export async function createRecord(input: { label: string; category: string; val: number }): Promise<AppRecord> {
  const res = await fetch('/api/records', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
  if (!res.ok) throw new Error('Failed to create record');
  return res.json();
}

export async function toggleRecordStatus(id: number): Promise<AppRecord> {
  const res = await fetch(`/api/records/${id}`, { method: 'PATCH' });
  if (!res.ok) throw new Error('Failed to update record');
  return res.json();
}

export async function deleteRecord(id: number): Promise<void> {
  const res = await fetch(`/api/records/${id}`, { method: 'DELETE' });
  if (!res.ok) throw new Error('Failed to delete record');
}

import express, { Request, Response } from 'express';
import cors from 'cors';
import { Pool } from 'pg';

const app = express();
const port = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://postgres:postgres@localhost:5432/kanban_db'
});

interface TaskRow {
  id: string;
  title: string;
  description: string | null;
  priority: 'Urgent' | 'High' | 'Medium' | 'Low';
  status: 'todo' | 'in_progress' | 'in_review' | 'done';
  assignee: string | null;
  tag: string | null;
  created_at: Date;
  updated_at: Date;
}

app.get('/api/tasks', async (req: Request, res: Response) => {
  try {
    const { priority, status, search } = req.query;
    let query = 'SELECT * FROM tasks WHERE 1=1';
    const params: any[] = [];

    if (priority && priority !== 'all') {
      params.push(priority);
      query += ` AND priority = $${params.length}`;
    }

    if (status) {
      params.push(status);
      query += ` AND status = $${params.length}`;
    }

    if (search) {
      params.push(`%${search}%`);
      query += ` AND (title ILIKE $${params.length} OR description ILIKE $${params.length} OR tag ILIKE $${params.length})`;
    }

    query += ' ORDER BY created_at DESC';
    const result = await pool.query(query, params);
    res.json(result.rows);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/tasks', async (req: Request, res: Response) => {
  try {
    const { title, description, priority, status, assignee, tag } = req.body;
    if (!title) {
      return res.status(400).json({ error: 'Title is required' });
    }
    const query = `
      INSERT INTO tasks (title, description, priority, status, assignee, tag)
      VALUES ($1, $2, $3, $4, $5, $6)
      RETURNING *
    `;
    const values = [title, description || null, priority || 'Medium', status || 'todo', assignee || null, tag || null];
    const result = await pool.query(query, values);
    res.status(201).json(result.rows[0]);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.patch('/api/tasks/:id/status', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { status } = req.body;
    const validStatuses = ['todo', 'in_progress', 'in_review', 'done'];
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ error: 'Invalid task status' });
    }
    const query = `
      UPDATE tasks 
      SET status = $1, updated_at = NOW()
      WHERE id = $2
      RETURNING *
    `;
    const result = await pool.query(query, [status, id]);
    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Task not found' });
    }
    res.json(result.rows[0]);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.put('/api/tasks/:id', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { title, description, priority, status, assignee, tag } = req.body;
    const query = `
      UPDATE tasks
      SET title = COALESCE($1, title),
          description = COALESCE($2, description),
          priority = COALESCE($3, priority),
          status = COALESCE($4, status),
          assignee = COALESCE($5, assignee),
          tag = COALESCE($6, tag),
          updated_at = NOW()
      WHERE id = $7
      RETURNING *
    `;
    const values = [title, description, priority, status, assignee, tag, id];
    const result = await pool.query(query, values);
    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Task not found' });
    }
    res.json(result.rows[0]);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/tasks/:id', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const result = await pool.query('DELETE FROM tasks WHERE id = $1 RETURNING id', [id]);
    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Task not found' });
    }
    res.json({ message: 'Task deleted successfully', id });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(port, () => {
  console.log(`Kanban API server running on port ${port}`);
});

